<?php
if(PHP_SAPI!=='cli'||getenv('SPP_DB_PORT')!=='58246'||getenv('SPP_TEST_ALLOW_MUTATION')!=='1')throw new RuntimeException('Private instance required');$_SESSION=['admin_id'=>1,'admin_role'=>'super_admin','active_unit_id'=>1];require __DIR__.'/../koneksi.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/spp_billing.php';require_once __DIR__.'/../includes/legacy_transactions.php';$db=$koneksi;if($db->query('SELECT @@server_uuid')->fetch_row()[0]!=='9d552e39-cbe6-11f1-9a5e-0a0027000012')throw new RuntimeException('Wrong instance');$checks=[];$check=function($ok,$label)use(&$checks){if(!$ok)throw new RuntimeException($label);$checks[]=$label;};
foreach([1,2,3] as $unit){$_SESSION['active_unit_id']=$unit;unit_set_context($db,$unit);lb_cache($db,true);
 $b=lf_one($db,"SELECT t.*,o.owner_id FROM tagihan_spp t JOIN siswa s ON s.NO_INDUK=t.no_induk AND s.unit_id=t.unit_id JOIN legacy_op_owners own ON own.student_id=s.id AND own.unit_id=s.unit_id JOIN legacy_op_obligations o ON o.owner_id=own.id AND o.unit_id=own.unit_id AND o.category='spp' AND o.period=CONCAT(t.tahun,'-',LPAD(t.bulan,2,'0')) WHERE t.status='open' ORDER BY t.id LIMIT 1");$check((bool)$b,"Unit $unit future Legacy SPP evidence found");$credit=lb_spp_credit($db,$b['no_induk'],$b['bulan'],$b['tahun']);$status=spp_published_period_status($db,$b['no_induk'],$b['bulan'],$b['tahun']);$check($credit>0&&$status['selected']['paid']>=$credit,"Unit $unit future SPP credit included exactly by period");
 $open=spp_open_bills($db,$b['no_induk']);$matching=array_values(array_filter($open,fn($v)=>$v['id']==$b['id']));$check($credit>=(float)$b['nominal_tagihan']?!$matching:abs($matching[0]['remaining']-((float)$b['nominal_tagihan']-$credit))<.001,"Unit $unit paid month not billed twice");
 $db->begin_transaction();try{$master=spp_master_state($db,(int)$b['master_spp_tahun_id']);$rates=spp_master_rates($db,(int)$master['id']);$version=spp_master_rate_version($master,$rates);$rates[(int)$b['tingkat_snapshot']]+=17000;spp_master_correct_published_rates($db,(int)$master['id'],$rates,$version,true);$saved=lf_one($db,'SELECT * FROM tagihan_spp WHERE id=?',[$b['id']]);$check($saved['nominal_tagihan']===$b['nominal_tagihan']&&$saved['tarif_dasar_snapshot']===$b['tarif_dasar_snapshot'],"Unit $unit historical SPP installment locks tariff snapshot");}finally{$db->rollback();lb_cache($db,true);}
 $p=null;foreach(lf_rows($db,'SELECT * FROM legacy_op_payments WHERE owner_id=? AND cancelled=0',[$b['owner_id']]) as $r)if(lb_payment_month($r['source_period'])===$b['tahun'].'-'.str_pad($b['bulan'],2,'0',STR_PAD_LEFT)){foreach(json_decode($r['items'],true) as $item)if($item['category']==='spp'&&lf_cents($item['amount'])>0){$p=$r;break 2;}}$check((bool)$p,"Unit $unit SPP credit traceable to exact receipt");
 $db->begin_transaction();try{$record=lop_record($db,'payment',(int)$p['id']);$input=['date'=>$record['source_date'],'period'=>$record['source_period'],'items'=>$record['items'],'cancelled'=>true,'reason'=>'Isolated SPP credit cancellation','confirmation'=>'SIMPAN KOREKSI','preview_expires'=>time()+300];$preview=lop_correction_preview($db,1,$unit,'payment',(int)$p['id'],(int)$p['version'],$input);lop_correction_apply($db,1,$unit,'payment',(int)$p['id'],(int)$p['version'],$input,$preview['digest'],bin2hex(random_bytes(32)),false);$newCredit=lb_spp_credit($db,$b['no_induk'],$b['bulan'],$b['tahun']);$check($newCredit<$credit,"Unit $unit cancellation restores SPP due atomically");$ob=lf_one($db,"SELECT remaining FROM legacy_op_obligations WHERE owner_id=? AND category='spp' AND period=?",[$b['owner_id'],$b['tahun'].'-'.str_pad($b['bulan'],2,'0',STR_PAD_LEFT)]);$check(abs((float)$ob['remaining']-max(0,(float)$b['nominal_tagihan']-$newCredit))<.001,"Unit $unit persisted SPP obligation reconciles");}finally{$db->rollback();lb_cache($db,true);}
}
